package com.sing.halfcloud.controller;

import android.app.*;
import android.content.*;
import android.database.Cursor;
import android.graphics.Typeface;
import android.net.Uri;
import android.os.Handler;
import android.os.Looper;
import android.provider.OpenableColumns;
import android.view.*;
import android.widget.*;
import okhttp3.*;
import org.json.*;
import java.io.*;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;

/** Native file browser, resumable transfers, command jobs and live status sheets. */
final class NativeTools {
    private final ControllerActivity host; private final ConsoleStyle ui; private final NativeSession session;
    private final Handler main=new Handler(Looper.getMainLooper());
    private Dialog dialog; private LinearLayout body,list; private TextView pathView,progress,output;
    private ProgressBar bar; private String folder="";private volatile String job="";private volatile boolean runningJob;private long outputOffset;
    private volatile boolean closed,cancelTransfer,busy;private File downloaded; private String downloadName;
    NativeTools(ControllerActivity host,ConsoleStyle ui,NativeSession session){this.host=host;this.ui=ui;this.session=session;}
    void close(){closed=true;cancelTransfer=true;main.removeCallbacksAndMessages(null);}
    private void ui(Runnable action){main.post(()->{if(!closed&&!host.isFinishing()&&!host.isDestroyed())action.run();});}
    private void error(Exception e){ui(()->message(e.getMessage()==null?"操作未完成，請重新嘗試。":e.getMessage()));}
    private void message(String text){Toast.makeText(host,text,Toast.LENGTH_LONG).show();if(progress!=null)progress.setText(text);}
    private LinearLayout row(String text,Runnable action){LinearLayout r=ui.row();r.setPadding(ui.dp(14),ui.dp(12),ui.dp(14),ui.dp(12));r.setBackground(ui.ripple(ui.inset()));TextView t=ui.text(text,14,ConsoleStyle.INK,false);r.addView(t,new LinearLayout.LayoutParams(-1,-2));r.setContentDescription(text);r.setOnClickListener(v->action.run());return r;}
    private void open(String title,String subtitle){body=ui.column();dialog=host.openToolSheet(title,subtitle,body);}
    private void statusLine(){progress=ui.text("",11,ConsoleStyle.MINT,false);body.addView(progress);bar=new ProgressBar(host,null,android.R.attr.progressBarStyleHorizontal);bar.setProgressTintList(android.content.res.ColorStateList.valueOf(ConsoleStyle.MINT));bar.setMax(1000);body.addView(bar,new LinearLayout.LayoutParams(-1,ui.dp(6)));ui.gap(body,12);}
    private static String query(String value){try{return URLEncoder.encode(value,"UTF-8");}catch(UnsupportedEncodingException impossible){throw new AssertionError(impossible);}}
    private static String size(long value){if(value<1024)return value+" B";return String.format(Locale.ROOT,value>=1048576?"%.1f MB":"%.1f KB",value/(value>=1048576?1048576.0:1024.0));}
    private void transferProgress(String label,long offset,long total){ui(()->{if(progress!=null)progress.setText(label+" · "+size(offset)+" / "+size(total));if(bar!=null)bar.setProgress(total==0?1000:(int)Math.min(1000,offset*1000/total));});}
    void files(){open("電話檔案","共用儲存空間 · 支援斷點續傳");pathView=ui.text("/sdcard",12,ConsoleStyle.MUTED,false);body.addView(pathView);ui.gap(body,12);LinearLayout actions=ui.row();actions.addView(row("↑ 上層",()->{int at=folder.lastIndexOf('/');folder=at<0?"":folder.substring(0,at);load(0);}),new LinearLayout.LayoutParams(0,-2,1));actions.addView(row("＋ 上傳",host::pickUpload),new LinearLayout.LayoutParams(0,-2,1));actions.addView(row("新增資料夾",this::newFolder),new LinearLayout.LayoutParams(0,-2,1));body.addView(actions);ui.gap(body,12);statusLine();body.addView(row("暫停傳輸",()->{cancelTransfer=true;message("已暫停；重新選取同一檔案可續傳。");}));ui.gap(body,12);list=ui.column();body.addView(list);load(0);}
    private void load(int offset){final String path=folder;final LinearLayout target=list;if(pathView!=null)pathView.setText("/sdcard"+(path.isEmpty()?"":"/"+path));if(offset==0)target.removeAllViews();session.backgroundTool(()->{try{JSONObject result=session.tool("GET","/api/tools/files?path="+query(path)+"&offset="+offset,null);JSONArray entries=result.getJSONArray("entries");ui(()->{if(target!=list||!path.equals(folder))return;for(int i=0;i<entries.length();i++){JSONObject entry=entries.optJSONObject(i);if(entry==null)continue;String name=entry.optString("name");boolean dir=entry.optBoolean("directory");target.addView(row((dir?"▣  ":"▤  ")+name+(dir?"":"   "+size(entry.optLong("size"))),()->{if(dir){folder=entry.optString("path");load(0);}else fileActions(entry);}));ui.gap(target,6);}int next=result.optInt("next_offset",-1);if(next>=0){LinearLayout more=row("載入更多",()->load(next));target.addView(more);}});}catch(Exception e){error(e);}});}
    private void newFolder(){EditText input=ui.input("資料夾名稱",false);new AlertDialog.Builder(host).setTitle("新增資料夾").setView(input).setNegativeButton("取消",null).setPositiveButton("建立",(d,w)->{String name=input.getText().toString().trim();if(name.isEmpty()||name.contains("/")||name.equals("..")){message("名稱無效");return;}operation("/api/tools/files/mkdir",join(folder,name));}).show();}
    private static String join(String path,String name){return path.isEmpty()?name:path+"/"+name;}
    private void operation(String path,String file){session.backgroundTool(()->{try{session.tool("POST",path,new JSONObject().put("path",file));ui(()->load(0));}catch(Exception e){error(e);}});}
    private void fileActions(JSONObject entry){String path=entry.optString("path"),name=entry.optString("name");boolean apk=name.toLowerCase(Locale.ROOT).endsWith(".apk");String[] items=apk?new String[]{"下載","安裝 APK","刪除"}:new String[]{"下載","刪除"};new AlertDialog.Builder(host).setTitle(name).setItems(items,(d,n)->{if(n==0)download(path,name);else if(apk&&n==1)new AlertDialog.Builder(host).setTitle("安裝 "+name+"？").setPositiveButton("安裝",(a,b)->install(path)).setNegativeButton("取消",null).show();else new AlertDialog.Builder(host).setTitle("刪除 "+name+"？").setPositiveButton("刪除",(a,b)->operation("/api/tools/files/remove",path)).setNegativeButton("取消",null).show();}).show();}
    private static String hex(byte[] bytes){StringBuilder s=new StringBuilder();for(byte b:bytes)s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
    private InputStream stream(Uri uri)throws IOException{InputStream in=host.getContentResolver().openInputStream(uri);if(in==null)throw new IOException("讀取檔案失敗");return in;}
    void upload(Uri uri){if(busy){message("請等候目前傳輸完成或暫停。");return;}busy=true;cancelTransfer=false;final String destination=folder;session.backgroundTool(()->{try{
        String name="upload.bin";try(Cursor c=host.getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}name=new File(name).getName();
        MessageDigest sha=MessageDigest.getInstance("SHA-256");long total=0;byte[] buffer=new byte[128*1024];ui(()->progress.setText("正在計算檔案校驗碼…"));try(InputStream in=stream(uri)){int n;while((n=in.read(buffer))!=-1){if(cancelTransfer||closed)return;sha.update(buffer,0,n);total+=n;if(total>16L*1024*1024*1024)throw new IOException("檔案超過 16 GB");}}
        final long length=total;JSONObject state=session.tool("POST","/api/tools/uploads",new JSONObject().put("path",join(destination,name)).put("size",total).put("sha256",hex(sha.digest())).put("overwrite",false));String id=state.getString("id");int failures=0;
        while(!state.optBoolean("complete")&&state.getLong("offset")<total){if(cancelTransfer||closed)return;long offset=state.getLong("offset");byte[] chunk;try(InputStream in=stream(uri)){long skip=offset;while(skip>0){long n=in.skip(skip);if(n==0){if(in.read()<0)throw new EOFException();n=1;}skip-=n;}ByteArrayOutputStream block=new ByteArrayOutputStream();long left=Math.min(512L*1024,total-offset);while(left>0){int n=in.read(buffer,0,(int)Math.min(buffer.length,left));if(n<0)throw new EOFException();block.write(buffer,0,n);left-=n;}chunk=block.toByteArray();}
            try(Response response=session.transfer(new Request.Builder().url(session.url("/api/tools/uploads/"+id+"?offset="+offset)).put(RequestBody.create(chunk,MediaType.get("application/octet-stream"))).build())){if(response.code()==401||response.code()==403)throw new SecurityException("授權已失效");if(response.code()!=200)throw new IOException("傳輸中斷（HTTP "+response.code()+"）");state=new JSONObject(response.body().string());failures=0;}catch(IOException e){if(++failures>5)throw e;Thread.sleep(Math.min(10000,failures*2000L));state=session.tool("GET","/api/tools/uploads/"+id,null);}
            transferProgress("上傳中",state.getLong("offset"),length);
        }
        if(cancelTransfer||closed)return;session.tool("POST","/api/tools/uploads/"+id+"/finish",new JSONObject());transferProgress("已上傳並通過 SHA-256",length,length);ui(()->{if(destination.equals(folder))load(0);});
    }catch(Exception e){error(e);}finally{busy=false;}});}
    private void download(String path,String name){if(busy){message("已有傳輸進行中");return;}busy=true;cancelTransfer=false;session.backgroundTool(()->{try{
        File dir=new File(host.getCacheDir(),"transfers");dir.mkdirs();String key=hex(MessageDigest.getInstance("SHA-256").digest((session.scope()+"/"+path).getBytes(StandardCharsets.UTF_8)));File part=new File(dir,key+".part"),tag=new File(dir,key+".etag");int failures=0;
        while(true){if(cancelTransfer||closed)return;long offset=part.length();String etag=tag.isFile()?new String(java.nio.file.Files.readAllBytes(tag.toPath()),StandardCharsets.UTF_8):"";Request.Builder req=new Request.Builder().url(session.url("/api/tools/files/download?path="+query(path)));if(offset>0&&!etag.isEmpty())req.header("Range","bytes="+offset+"-").header("If-Range",etag);
            try(Response res=session.transfer(req.build())){if(res.code()==401||res.code()==403)throw new SecurityException("授權已失效");if(res.code()==416&&offset>0&&!etag.isEmpty()&&res.header("Content-Range","").equals("bytes */"+offset)){downloaded=part;downloadName=name;ui(()->host.saveDownload(name));break;}if(res.code()!=200&&res.code()!=206)throw new IOException("下載失敗（HTTP "+res.code()+"）");boolean append=res.code()==206;if(append&&!res.header("Content-Range","").startsWith("bytes "+offset+"-"))throw new IOException("續傳位置無效");if(!append)offset=0;String newTag=res.header("ETag","");java.nio.file.Files.write(tag.toPath(),newTag.getBytes(StandardCharsets.UTF_8));long length=res.body().contentLength(),total=length<0?0:offset+length,done=offset;try(InputStream in=res.body().byteStream();FileOutputStream out=new FileOutputStream(part,append)){byte[] b=new byte[128*1024];int n;while((n=in.read(b))!=-1){if(cancelTransfer||closed)return;out.write(b,0,n);done+=n;transferProgress("下載中",done,total);}}if(total>0&&done!=total)throw new EOFException();downloaded=part;downloadName=name;ui(()->host.saveDownload(name));break;}catch(IOException e){if(++failures>5)throw e;Thread.sleep(Math.min(10000,failures*2000L));}
        }
    }catch(Exception e){error(e);}finally{busy=false;}});}
    void save(Uri uri){final File file=downloaded;if(file==null)return;session.backgroundTool(()->{try(InputStream in=new FileInputStream(file);OutputStream out=host.getContentResolver().openOutputStream(uri,"w")){if(out==null)throw new IOException("儲存失敗");byte[] b=new byte[128*1024];int n;while((n=in.read(b))!=-1)out.write(b,0,n);ui(()->message("已儲存 "+downloadName));}catch(Exception e){error(e);}});}
    void terminal(){open("Root 終端","指令喺受控電話執行 · 最長 120 秒");EditText command=ui.input("輸入指令，例如 id",false);command.setSingleLine(false);command.setTypeface(Typeface.MONOSPACE);body.addView(command);ui.gap(body,12);LinearLayout actions=ui.row();actions.addView(row("執行",()->{if(!job.isEmpty()){message("請等候目前指令完成");return;}run(command.getText().toString(),false);}),new LinearLayout.LayoutParams(0,-2,1));actions.addView(row("儲存",()->saveScript(command.getText().toString())),new LinearLayout.LayoutParams(0,-2,1));actions.addView(row("常用指令",()->scripts(command)),new LinearLayout.LayoutParams(0,-2,1));actions.addView(row("停止",()->cancelJob()),new LinearLayout.LayoutParams(0,-2,1));body.addView(actions);ui.gap(body,16);output=ui.text("$ ",12,ConsoleStyle.INK,false);output.setTypeface(Typeface.MONOSPACE);output.setTextIsSelectable(true);body.addView(output);}
    private void saveScript(String command){if(command.trim().isEmpty())return;EditText title=ui.input("名稱",false);new AlertDialog.Builder(host).setTitle("儲存常用指令").setView(title).setPositiveButton("儲存",(d,w)->{try{JSONObject scripts=new JSONObject(host.getPreferences(0).getString("scripts","{}"));String name=title.getText().toString().trim();if(name.isEmpty())return;scripts.put(name,command);host.getPreferences(0).edit().putString("scripts",scripts.toString()).apply();message("已儲存");}catch(Exception e){error(e);}}).setNegativeButton("取消",null).show();}
    private void scripts(EditText target){try{JSONObject scripts=new JSONObject(host.getPreferences(0).getString("scripts","{}"));ArrayList<String> names=new ArrayList<>();scripts.keys().forEachRemaining(names::add);if(names.isEmpty()){message("暫時未有常用指令");return;}new AlertDialog.Builder(host).setTitle("常用指令").setItems(names.toArray(new String[0]),(d,w)->{String name=names.get(w);target.setText(scripts.optString(name));}).setNegativeButton("關閉",null).setNeutralButton("清除全部",(d,w)->host.getPreferences(0).edit().remove("scripts").apply()).show();}catch(Exception e){error(e);}}
    private void install(String path){if(runningJob){message("請先完成或停止目前指令。");return;}open("安裝 APK","由受控電話執行 Android 套件安裝");output=ui.text("正在準備安裝…",12,ConsoleStyle.INK,false);output.setTypeface(Typeface.MONOSPACE);output.setTextIsSelectable(true);body.addView(output);run(path,true);}
    private void run(String command,boolean apk){if(command.trim().isEmpty())return;if(runningJob){message("目前仍有指令執行中。");return;}runningJob=true;final TextView target=output;session.backgroundTool(()->{try{JSONObject result=session.tool("POST",apk?"/api/tools/apk/install":"/api/tools/terminal/jobs",apk?new JSONObject().put("path",command):new JSONObject().put("command",command).put("timeout_seconds",120));job=result.getString("id");outputOffset=0;StringBuilder text=new StringBuilder();ui(()->target.setText(apk?"正在安裝…":"$ "+command+"\n"));while(!closed){JSONObject poll=session.tool("GET","/api/tools/terminal/jobs/"+job+"?offset="+outputOffset,null);outputOffset=poll.getLong("offset");text.append(poll.optString("output"));if(text.length()>131072)text.delete(0,text.length()-131072);String value=text.toString();boolean done=poll.optBoolean("done");ui(()->target.setText(value+(done?"\n[結束代碼 "+poll.optInt("exit_code")+"]":"")));if(done)break;Thread.sleep(450);}}catch(Exception e){error(e);}finally{job="";runningJob=false;}});}
    private void cancelJob(){final String id=job;if(id.isEmpty())return;session.backgroundTool(()->{try{session.tool("POST","/api/tools/terminal/jobs/"+id+"/cancel",new JSONObject());}catch(Exception e){error(e);}});}
    void dashboard(){open("電話與中繼","每 15 秒更新 · 流量由主機網卡統計");TextView details=ui.text("正在讀取電話狀態…",14,ConsoleStyle.INK,false);details.setLineSpacing(ui.dp(7),1);body.addView(details);ui.gap(body,20);TextView relays=ui.text("正在讀取中繼流量…",13,ConsoleStyle.MUTED,false);relays.setLineSpacing(ui.dp(7),1);body.addView(relays);final Dialog panel=dialog;Runnable refresh=new Runnable(){public void run(){if(closed||!panel.isShowing())return;session.backgroundTool(()->{try{JSONObject state=session.tool("GET","/api/tools/status",null),device=state.optJSONObject("device");String text="受控端 v"+state.optString("version")+" · "+(state.optBoolean("root")?"Root 已就緒":"Root 未就緒");if(device!=null)text+="\n"+device.optString("model")+" · Android "+device.optString("android")+"\n電量 "+(device.has("battery_percent")?device.optInt("battery_percent")+"%":"未取得")+(device.optBoolean("charging")?" · 充電中":"")+"\n溫度 "+(device.has("temperature_c")?device.optDouble("temperature_c")+"°C":"未取得")+"\n"+device.optString("network");final String view=text;ui(()->details.setText(view));}catch(Exception e){ui(()->details.setText("電話狀態未能取得："+e.getMessage()));}try{JSONArray nodes=session.tool("GET","/_remoteconsole/relays/status",null).getJSONArray("relays");StringBuilder text=new StringBuilder("中繼流量 · 香港時間\n");if(nodes.length()==0)text.append("未接駁流量回報");for(int i=0;i<nodes.length();i++){JSONObject node=nodes.getJSONObject(i);text.append("\n").append(node.optString("name")).append(node.optBoolean("available")?" · 已更新":" · 回報暫未更新");JSONObject report=node.optJSONObject("report");if(report!=null){for(String period:new String[]{"day","month","total"}){JSONObject n=report.optJSONObject(period);if(n!=null)text.append("\n").append(period.equals("day")?"今日":period.equals("month")?"本月":"累計").append("  入 ").append(size(n.optLong("rx"))).append(" / 出 ").append(size(n.optLong("tx")));}if(report.optDouble("quota_gb")>0)text.append("\n參考額度 ").append(report.optDouble("quota_gb")).append(" GB");if(node.has("warning"))text.append("\n⚠ ").append(node.optString("warning"));}}String value=text.toString();ui(()->relays.setText(value));}catch(Exception e){ui(()->relays.setText("中繼流量未能取得；請升級入口並啟用香港流量回報。"));}main.postDelayed(this,15000);});}};main.post(refresh);}
}
